-- Réinitialisation du statut formation de tous les convoyeurs
UPDATE public.convoyeurs
SET has_completed_training = false,
    training_status = 'not_started',
    training_completed_at = NULL;

-- 2. INSERTION DES 10 MODULES
INSERT INTO public.formation_modules (slug, title, description, content_type, content_url, content_body, quiz_questions, sections, minimum_score, estimated_minutes, sort_order, is_active, is_required, category) VALUES
  ('comprendre-le-metier', 'Comprendre le métier de convoyeur automobile', 'Rôle, responsabilités et posture professionnelle du convoyeur Ligneo.', 'text', NULL, NULL, '[{"question": "À partir de quand le convoyeur est-il responsable du véhicule ?", "choices": ["Dès la signature de l''état des lieux de départ", "Dès le démarrage du moteur", "À l''arrivée chez le client"], "answer": 0, "explanation": "La responsabilité débute à la signature de l''état des lieux de départ et se termine à la signature de livraison."}, {"question": "Que représente le convoyeur pendant sa mission ?", "choices": ["Un simple livreur", "L''image et les valeurs de Transports Ligneo", "Un client comme les autres"], "answer": 1, "explanation": "Le convoyeur est l''ambassadeur de l''entreprise auprès du client."}, {"question": "Que faire en cas d''incident, même mineur ?", "choices": ["Le signaler immédiatement", "Attendre la fin de la mission", "Ne rien dire si ce n''est pas grave"], "answer": 0, "explanation": "Tout incident doit être signalé immédiatement pour traitement et traçabilité."}, {"question": "Lequel de ces comportements est attendu ?", "choices": ["Improviser pour aller plus vite", "Respecter strictement les procédures", "Négocier les horaires avec le client"], "answer": 1, "explanation": "Aucune improvisation : les procédures de sécurité sont non négociables."}]'::jsonb, '[{"type": "text", "content": "Le convoyeur Transports Ligneo prend en charge un véhicule chez un client ou un site partenaire et le livre à un autre endroit, en garantissant son intégrité, sa sécurité et le respect des délais. Il représente Transports Ligneo pendant toute la mission : son comportement, sa tenue et sa communication sont perçus comme ceux de l''entreprise."}, {"type": "image", "url": "[IMAGE: convoyeur en tenue professionnelle remettant les clés d''une voiture à un client, devant un véhicule berline]", "alt": "Convoyeur professionnel remettant les clés", "caption": "Le convoyeur est l''ambassadeur de Transports Ligneo sur le terrain."}, {"type": "text", "content": "Ce qu''on attend de vous :\n\n• Ponctualité stricte sur les horaires de prise en charge et de livraison.\n• Neutralité et professionnalisme, quel que soit le client.\n• Zéro improvisation sur les procédures de sécurité.\n• Signalement immédiat de tout incident, aussi mineur soit-il."}, {"type": "callout", "tone": "warning", "content": "⚠️ Point clé : le convoyeur est responsable du véhicule dès la signature de l''état des lieux de départ jusqu''à la signature de livraison. Tout dommage non documenté à l''aller est présumé causé pendant le transport."}, {"type": "image", "url": "[IMAGE: gros plan sur une tablette avec une checklist numérique d''état des lieux]", "alt": "Checklist numérique d''état des lieux", "caption": "La documentation protège le convoyeur et garantit la traçabilité."}, {"type": "checklist", "items": ["Je lis attentivement le dossier mission avant de partir.", "Je vérifie ma tenue et mon équipement.", "Je me présente comme un professionnel Transports Ligneo.", "Je signale tout écart immédiatement."]}]'::jsonb, 80, 10, 10, true, true, 'métier'),
  ('preparation-prise-en-charge', 'Préparation et prise en charge du véhicule', 'Vérifications obligatoires avant tout départ et posture professionnelle au point de retrait.', 'text', NULL, NULL, '[{"question": "Que faire si l''adresse exacte de livraison est incomplète ?", "choices": ["Partir quand même", "Contacter le dispatch pour compléter le dossier", "Annuler la mission"], "answer": 1, "explanation": "Un dossier incomplet doit être complété avant le départ."}, {"question": "Quels documents sont obligatoires avant la prise en charge ?", "choices": ["Carte grise et assurance", "Seulement le permis du convoyeur", "Aucun document"], "answer": 0, "explanation": "La carte grise, l''assurance et les documents obligatoires doivent être vérifiés."}, {"question": "Comment se présenter au point de retrait ?", "choices": ["En anonyme", "Nom + Transports Ligneo, courtoisie et professionnalisme", "En demandant juste les clés"], "answer": 1, "explanation": "La présentation professionnelle rassure le contact et représente Ligneo."}, {"question": "Que vérifier impérativement avant de signer l''état des lieux de départ ?", "choices": ["L''état visuel du véhicule et le kilométrage", "La couleur des sièges uniquement", "Rien, le client s''en charge"], "answer": 0, "explanation": "L''état visuel, le kilométrage et le niveau de carburant/charge doivent être vérifiés et documentés."}]'::jsonb, '[{"type": "text", "content": "Avant de démarrer, le convoyeur doit s''assurer que le dossier mission est complet : identité du contact, adresses de retrait et de livraison, horaires, documents véhicule et consignes spécifiques. Un dossier incomplet doit être complété avant le départ."}, {"type": "checklist", "items": ["Dossier mission lu et compris", "Contact de retrait confirmé", "Adresses et horaires vérifiés", "Documents véhicule présents (carte grise, assurance, etc.)"]}, {"type": "callout", "tone": "warning", "content": "⚠️ Point clé : un véhicule ne doit jamais être pris en charge sans ses documents obligatoires. Le signalement en amont évite un blocage sur place."}, {"type": "image", "url": "[IMAGE: convoyeur vérifiant les documents du véhicule sur le pare-brise avant départ]", "alt": "Vérification des documents véhicule", "caption": "Les documents sont aussi importants que l''état du véhicule."}, {"type": "text", "content": "Au point de retrait, présentez-vous en annonçant votre nom et votre provenance (Transports Ligneo), soyez courtois et patient. Vérifiez l''identité du contact, inspectez le véhicule avant de signer quoi que ce soit et notez le kilométrage ainsi que le niveau de carburant/charge."}]'::jsonb, 80, 10, 20, true, true, 'préparation'),
  ('etat-des-lieux-depart', 'L''état des lieux de départ', 'Inspection complète, photos probantes et documentation avant le départ.', 'text', NULL, NULL, '[{"question": "Combien de faces extérieures doit-on photographier au minimum ?", "choices": ["1", "2", "4"], "answer": 2, "explanation": "Les 4 faces extérieures doivent être photographiées systématiquement."}, {"question": "Que faire en cas de dommage visible au départ ?", "choices": ["L''ignorer", "Photographier, signaler et faire mentionner sur l''état des lieux", "Réparer soi-même"], "answer": 1, "explanation": "Tout dommage doit être documenté et signalé avant le départ."}, {"question": "Peut-on signer un état des lieux vierge ?", "choices": ["Oui, si le client est pressé", "Non, jamais", "Oui, parfois"], "answer": 1, "explanation": "Un état des lieux vierge ne protège ni le convoyeur ni le client."}, {"question": "Quels éléments doivent être notés en plus des photos ?", "choices": ["Kilométrage et niveau carburant/charge", "La marque du véhicule uniquement", "Rien de plus"], "answer": 0, "explanation": "Le kilométrage et le niveau de carburant/charge sont des données contractuelles essentielles."}]'::jsonb, '[{"type": "text", "content": "L''état des lieux est la protection du convoyeur et du client. Il se fait avant de signer le document de prise en charge. Chaque dommage, rayure, éclat ou anomalie doit être photographié et noté."}, {"type": "image", "url": "[IMAGE: série de 4 photos d''un véhicule : avant, arrière, côté gauche, côté droit]", "alt": "Photos des 4 faces du véhicule", "caption": "Les 4 faces du véhicule doivent être photographiées systématiquement."}, {"type": "checklist", "items": ["4 faces extérieures photographiées", "Intérieur et tableau de bord photographiés", "Kilométrage noté", "Niveau de carburant / charge noté", "Dommages signalés et photographiés", "État des pneus et jantes vérifié"]}, {"type": "callout", "tone": "warning", "content": "⚠️ Point clé : un état des lieux non fait = une mission non protégée. Ne signez jamais un document vierge ou incomplet."}, {"type": "text", "content": "En cas de dommage visible au départ, photographiez-le sous plusieurs angles, signalez-le immédiatement au contact et faites le mentionner sur l''état des lieux. Si le contact refuse, contactez le dispatch avant de partir."}, {"type": "image", "url": "[IMAGE: gros plan sur une rayure de carrosserie photographiée avec un smartphone]", "alt": "Photographie d''un dommage", "caption": "Un dommage photographié est un dommage prouvé."}]'::jsonb, 80, 12, 30, true, true, 'inspection'),
  ('conduite-securite-routiere', 'Conduite et sécurité routière', 'Adopter une conduite adaptée, respecter le code de la route et anticiper les risques.', 'text', NULL, NULL, '[{"question": "Quel type de conduite est attendu pendant un convoyage ?", "choices": ["Sportive pour gagner du temps", "Souple, prévisible et respectueuse du code", "Lente à 20 km/h sous la limite"], "answer": 1, "explanation": "La conduite doit être professionnelle, sécurisée et respectueuse."}, {"question": "Peut-on utiliser son téléphone au volant ?", "choices": ["Oui, pour le GPS", "Non, jamais", "Oui, en mode mains-libres uniquement si légal"], "answer": 1, "explanation": "L''utilisation du téléphone au volant est interdite et dangereuse."}, {"question": "Que faire en cas d''alerte météo sur l''itinéraire ?", "choices": ["Continuer normalement", "Adapter la conduite et informer le dispatch", "Annuler seul la mission"], "answer": 1, "explanation": "Il faut adapter sa conduite et communiquer avec le dispatch."}, {"question": "Sur un long trajet, quelle pratique est recommandée ?", "choices": ["Conduire sans s''arrêter", "Faire des pauses régulières", "Augmenter la vitesse pour finir plus tôt"], "answer": 1, "explanation": "Les pauses régulières limitent la fatigue et les risques d''accident."}]'::jsonb, '[{"type": "text", "content": "Le convoyeur conduit un véhicule qui ne lui appartient pas, souvent de forte valeur. La conduite doit être souple, prévisible et respectueuse du code de la route. Aucune sportivité, aucune imprudence."}, {"type": "callout", "tone": "warning", "content": "⚠️ Point clé : la vitesse et la conduite pendant le convoyage doivent respecter strictement le code de la route. Le client ne peut pas vous demander d''enfreindre la loi."}, {"type": "checklist", "items": ["Respect des limitations de vitesse", "Distance de sécurité respectée", "Manœuvres prévisibles et fluides", "Aucune utilisation du téléphone au volant", "Arrêts réguliers sur les longs trajets"]}, {"type": "image", "url": "[IMAGE: vue depuis le pare-brise d''une conduite calme sur autoroute par temps clair]", "alt": "Conduite sécurisée sur autoroute", "caption": "Une conduite fluide et prévisible protège le véhicule et les autres usagers."}, {"type": "text", "content": "Anticipez les aléas météo, le trafic et la fatigue. En cas de conditions difficiles, adaptez votre vitesse, augmentez les distances et informez le dispatch si un retard est probable."}]'::jsonb, 80, 10, 40, true, true, 'sécurité'),
  ('communication-relation-client', 'Communication et relation client', 'Professionnalisme, écoute active et gestion des attentes du client.', 'text', NULL, NULL, '[{"question": "Que faire si un client est mécontent ?", "choices": ["L''ignorer", "L''écouter avec calme et remonter au dispatch", "Lui répondre fermement"], "answer": 1, "explanation": "L''écoute active et la remontée au dispatch permettent une gestion professionnelle."}, {"question": "Le client demande un service hors mission. Que répondre ?", "choices": ["Accepter directement", "Refuser brutalement", "Ne pas s''engager seul et remonter au dispatch"], "answer": 2, "explanation": "Seul le dispatch peut valider une modification de mission."}, {"question": "Quelle information communiquer en cas de retard prévisible ?", "choices": ["Rien, ce n''est pas important", "Prévenir le client et le dispatch", "Uniquement le dispatch"], "answer": 1, "explanation": "Le client et le dispatch doivent être tenus informés."}, {"question": "Quelle est la priorité dans la relation client ?", "choices": ["La rapidité", "Le respect et le professionnalisme", "Le silence pour ne pas déranger"], "answer": 1, "explanation": "Le respect du client et le professionnalisme priment sur la vitesse."}]'::jsonb, '[{"type": "text", "content": "Le convoyeur est en contact direct avec le client ou son représentant. Sa communication doit être claire, courtoise et professionnelle. Le respect du client passe avant la rapidité."}, {"type": "callout", "tone": "info", "content": "💡 Astuce : annoncez vos horaires de passage, soyez ponctuel et tenez le client informé en cas de retard prévisible."}, {"type": "checklist", "items": ["Présentation claire (nom + Transports Ligneo)", "Explication des étapes de la mission", "Écoute active et reformulation", "Restez calme face à un client mécontent", "Remontez les demandes particulières au dispatch"]}, {"type": "image", "url": "[IMAGE: convoyeur serrant la main d''un client avec le sourire, devant un véhicule]", "alt": "Relation client professionnelle", "caption": "Le premier contact client est déterminant pour l''image de Ligneo."}, {"type": "text", "content": "Si le client est mécontent ou demande un service hors mission, écoutez-le avec calme, ne vous engagez pas seul et remontez la demande au dispatch. Ne promettez rien que Ligneo n''a pas validé."}]'::jsonb, 80, 10, 50, true, true, 'relation client'),
  ('gestion-incidents', 'Gestion des incidents et imprévus', 'Procédures en cas d''accident, panne, dommage ou retard.', 'text', NULL, NULL, '[{"question": "En cas d''accident, quelle est la première action ?", "choices": ["Appeler le client", "Sécuriser les personnes", "Déplacer le véhicule"], "answer": 1, "explanation": "La sécurité des personnes est la priorité absolue."}, {"question": "Que faire après un incident mineur (rayure, éclat) ?", "choices": ["Le cacher", "Le photographier et le signaler", "Le réparer soi-même"], "answer": 1, "explanation": "Tout incident doit être documenté et signalé."}, {"question": "En cas de panne, peut-on réparer le véhicule soi-même ?", "choices": ["Oui, pour gagner du temps", "Non, on contacte le dispatch et l''assistance", "Seulement si c''est simple"], "answer": 1, "explanation": "La réparation est réservée aux professionnels agréés."}, {"question": "Qui contacter en premier en cas d''incident ?", "choices": ["Le client final", "Les secours si besoin, puis le dispatch Ligneo", "Personne, pour ne pas inquiéter"], "answer": 1, "explanation": "Les secours si nécessaire, puis le dispatch Ligneo pour coordination."}]'::jsonb, '[{"type": "text", "content": "Même avec toute la vigilance du monde, un incident peut survenir. La règle d''or : sécuriser les personnes, puis informer Transports Ligneo. Jamais dissimuler, jamais improviser."}, {"type": "callout", "tone": "warning", "content": "⚠️ Point clé : en cas d''accident, la première action est de sécuriser les personnes, puis de contacter Ligneo. Ne déplacez pas le véhicule avant d''avoir documenté la scène si c''est sûr."}, {"type": "checklist", "items": ["Sécuriser les personnes et le site", "Alerter les secours si nécessaire", "Photographier la scène et les dommages", "Contacter le dispatch Ligneo", "Remplir un constat si nécessaire", "Ne pas reconnaître de responsabilité seul"]}, {"type": "image", "url": "[IMAGE: convoyeur utilisant son téléphone à l''écart de la route après un incident, véhicule sécurisé]", "alt": "Signalement d''incident", "caption": "Le signalement immédiat protège toutes les parties."}, {"type": "text", "content": "En cas de panne, stationnez le véhicule en lieu sûr, activez les feux de détresse, contactez le dispatch et l''assistance. Ne tentez pas de réparer vous-même un véhicule que vous ne connaissez pas."}]'::jsonb, 80, 10, 60, true, true, 'sécurité'),
  ('application-ligneo', 'Utilisation de l''application Ligneo', 'Suivi de mission, photos, signatures et communication avec le dispatch.', 'text', NULL, NULL, '[{"question": "Quand l''application Ligneo doit-elle être connectée ?", "choices": ["Uniquement au début", "Pendant toute la mission", "Seulement à la fin"], "answer": 1, "explanation": "L''application doit rester connectée pendant toute la mission."}, {"question": "Que faire des photos prises pendant la mission ?", "choices": ["Les garder sur son téléphone", "Les uploader immédiatement dans l''app", "Les envoyer par SMS"], "answer": 1, "explanation": "Les photos doivent être uploadées dans l''application pour traçabilité."}, {"question": "Pourquoi mettre à jour le statut de mission à chaque étape ?", "choices": ["Pour le suivi temps réel par le dispatch et le client", "Ce n''est pas utile", "Uniquement pour le convoyeur"], "answer": 0, "explanation": "Les mises à jour de statut permettent le suivi en temps réel."}, {"question": "Que vérifier avant chaque mission ?", "choices": ["Batterie, connexion et version de l''app", "Rien de spécial", "Uniquement le GPS"], "answer": 0, "explanation": "Batterie, connexion et version à jour sont essentiels."}]'::jsonb, '[{"type": "text", "content": "L''application mobile Transports Ligneo est votre outil de travail principal. Elle doit être à jour et connectée pendant toute la mission. C''est elle qui centralise les photos, les signatures, les incidents et la géolocalisation."}, {"type": "callout", "tone": "info", "content": "💡 Astuce : vérifiez votre batterie et votre connexion avant chaque mission. Une photo non envoyée est une preuve qui n''existe pas."}, {"type": "checklist", "items": ["Application à jour", "Connexion internet ou données mobiles activées", "Batterie suffisante", "Photos uploadées immédiatement", "Signatures collectées sur l''app", "Statut de mission mis à jour à chaque étape"]}, {"type": "image", "url": "[IMAGE: smartphone affichant l''application Ligneo avec un état des lieux numérique]", "alt": "Application mobile Ligneo", "caption": "L''application centralise la traçabilité de la mission."}, {"type": "text", "content": "À chaque étape clé (arrivée au retrait, départ, arrivée à la livraison), mettez à jour le statut dans l''application. Cela permet au dispatch de suivre la mission en temps réel et d''informer le client."}]'::jsonb, 80, 10, 70, true, true, 'outils'),
  ('rgpd-confidentialite', 'RGPD et confidentialité', 'Protection des données client et respect de la vie privée.', 'text', NULL, NULL, '[{"question": "Que faire des données personnelles du client ?", "choices": ["Les partager avec des collègues", "Les protéger et ne pas les conserver", "Les publier anonymement"], "answer": 1, "explanation": "Les données client sont confidentielles et ne doivent pas être conservées."}, {"question": "Peut-on photographier le client pour les réseaux sociaux ?", "choices": ["Oui, sans son visage", "Non, jamais sans accord écrit", "Oui, si la mission s''est bien passée"], "answer": 1, "explanation": "Aucune photo identifiable sans consentement explicite."}, {"question": "Que faire d''un objet personnel trouvé dans le véhicule ?", "choices": ["Le garder", "Le jeter", "Le signaler via l''app pour remise au client"], "answer": 2, "explanation": "Les objets trouvés doivent être signalés et remis selon la procédure."}, {"question": "Quelle réglementation protège les données client ?", "choices": ["RGPD", "Code de la route", "Aucune"], "answer": 0, "explanation": "Le RGPD protège les données personnelles en Europe."}]'::jsonb, '[{"type": "text", "content": "Pendant une mission, le convoyeur accède à des données personnelles : nom, adresse, téléphone, documents du véhicule, photos. Ces données sont strictement confidentielles et protégées par le RGPD."}, {"type": "callout", "tone": "warning", "content": "⚠️ Point clé : les données du client sont confidentielles et protégées. Jamais les partager sur les réseaux sociaux, les transmettre à des tiers ou les conserver après la mission."}, {"type": "checklist", "items": ["Pas de photo ou vidéo personnelle du client sans accord", "Pas de partage sur les réseaux sociaux", "Pas de conservation de données après la mission", "Signalement immédiat en cas de fuite de données", "Utilisation professionnelle uniquement des documents"]}, {"type": "image", "url": "[IMAGE: cadenas numérique sur fond bleu marine, symbolisant la protection des données]", "alt": "Protection des données", "caption": "La confidentialité est une obligation légale et déontologique."}, {"type": "text", "content": "Si vous trouvez des objets personnels dans le véhicule, ne les jetez pas et ne les gardez pas. Signalez-les via l''application pour qu''ils soient remis au client selon la procédure Ligneo."}]'::jsonb, 80, 8, 80, true, true, 'conformité'),
  ('livraison-vehicule', 'Livraison du véhicule', 'Préparation, état des lieux d''arrivée et clôture professionnelle de la mission.', 'text', NULL, NULL, '[{"question": "Que doit-on vérifier juste avant de descendre du véhicule à la livraison ?", "choices": ["Son propre téléphone", "L''état du véhicule", "La radio"], "answer": 1, "explanation": "Un dernier contrôle visuel du véhicule est nécessaire avant la livraison."}, {"question": "Que compare-t-on à la livraison ?", "choices": ["L''état des lieux de départ", "Le prix de la mission", "L''itinéraire"], "answer": 0, "explanation": "On compare l''état du véhicule avec l''état des lieux de départ."}, {"question": "Quand la mission est-elle réellement terminée ?", "choices": ["Après signature de l''état des lieux de livraison et remise des clés", "Dès l''arrivée sur place", "Après avoir dit au revoir"], "answer": 0, "explanation": "La clôture administrative et matérielle marque la fin de la mission."}, {"question": "Que faire si un écart est constaté par rapport au départ ?", "choices": ["L''ignorer", "L''expliquer au client et le documenter", "Accuser le client"], "answer": 1, "explanation": "Tout écart doit être expliqué et documenté."}]'::jsonb, '[{"type": "text", "content": "La livraison est l''étape finale et visible de la mission. Prévenez le client de l''heure d''arrivée, vérifiez une dernière fois l''état du véhicule avant de descendre et soyez ponctuel."}, {"type": "checklist", "items": ["Client prévenu de l''heure d''arrivée", "Véhicule propre et en bon état apparent", "Documents prêts", "Photos de livraison à prendre", "Signature du destinataire prévue"]}, {"type": "callout", "tone": "warning", "content": "⚠️ Point clé : la mission n''est terminée qu''après signature de l''état des lieux de livraison ET remise des clés en main propre (ou selon la procédure définie pour le point de livraison)."}, {"type": "image", "url": "[IMAGE: convoyeur et client faisant ensemble le tour du véhicule à la livraison]", "alt": "État des lieux de livraison", "caption": "L''état des lieux de livraison se fait avec le client, en comparant avec le départ."}, {"type": "text", "content": "Faites le tour du véhicule avec le client, comparez avec l''état des lieux de départ et expliquez tout écart constaté pendant le trajet. Photographiez l''état final, collectez la signature et remettez les clés selon la procédure."}]'::jsonb, 80, 10, 90, true, true, 'livraison'),
  ('qualite-standard-ligneo', 'Qualité et standard Transports Ligneo', 'Les 10 règles d''or et l''esprit de service Ligneo.', 'text', NULL, NULL, '[{"question": "Que protègent les documents et photos ?", "choices": ["Le convoyeur et le client", "Uniquement le client", "Personne"], "answer": 0, "explanation": "La documentation protège toutes les parties en cas de litige."}, {"question": "Que passe le respect du client devant, selon les règles d''or ?", "choices": ["La rapidité", "La sécurité", "Le coût"], "answer": 0, "explanation": "Le respect du client prime sur la rapidité."}, {"question": "Qui représente l''image de Transports Ligneo pendant une mission ?", "choices": ["Le convoyeur", "Le dispatch", "Le client"], "answer": 0, "explanation": "Le convoyeur est l''ambassadeur de Ligneo sur le terrain."}, {"question": "Que renforce chaque mission réussie ?", "choices": ["La confiance du client et la réputation de l''entreprise", "Le salaire du convoyeur", "Le prix de la mission"], "answer": 0, "explanation": "Chaque mission réussie contribue à la réputation de Ligneo."}]'::jsonb, '[{"type": "text", "content": "Chaque mission réussie renforce la confiance du client et la réputation de l''entreprise. La qualité ne se voit pas seulement dans le résultat final, mais dans chaque étape du processus."}, {"type": "callout", "tone": "info", "content": "⭐ Les 10 règles d''or du convoyeur Ligneo :\n1. La sécurité avant tout, toujours.\n2. Un état des lieux non fait = une mission non protégée.\n3. Le véhicule du client est traité comme s''il était le vôtre.\n4. La ponctualité n''est pas négociable.\n5. Tout incident se signale, jamais ne se cache.\n6. Le respect du client passe avant la rapidité.\n7. Les documents et photos sont votre meilleure protection.\n8. Aucune improvisation sur les procédures de sécurité.\n9. La communication avec le dispatching est continue, pas seulement en cas de problème.\n10. L''image de Transports Ligneo, c''est vous."}, {"type": "image", "url": "[IMAGE: visuel récapitulatif type affiche avec les 10 règles d''or et le logo Transports Ligneo]", "alt": "Les 10 règles d''or Ligneo", "caption": "Ces règles guident chaque décision sur le terrain."}, {"type": "checklist", "items": ["Je connais les 10 règles d''or", "Je comprends que chaque détail compte", "Je suis prêt à représenter Ligneo avec excellence", "Je sais que la qualité se joue à chaque étape"]}, {"type": "text", "content": "L''esprit de service Ligneo, c''est la combinaison du professionnalisme, de l''anticipation et de l''écoute. En appliquant ces standards, vous devenez un convoyeur autonome, fiable et reconnu."}]'::jsonb, 80, 8, 100, true, true, 'qualité');

-- 3. INSERTION DE L'EXAMEN FINAL
INSERT INTO public.formation_exams (title, description, question_pool, question_count, time_limit_minutes, minimum_score, is_active)
VALUES (
  'Examen final — Certification convoyeur Transports Ligneo',
  'Examen professionnel de 50 questions couvrant l''ensemble de l''académie. Durée : 50 minutes. Seuil de réussite : 80 %.',
  '[{"question": "Le convoyeur est responsable du véhicule à partir de quel moment ?", "choices": ["Dès la signature de l''état des lieux de départ", "Dès l''arrivée chez le client", "Dès le paiement"], "answer": 0, "explanation": "La responsabilité débute à la signature de l''état des lieux de départ."}, {"question": "Le convoyeur représente :", "choices": ["Lui-même uniquement", "Transports Ligneo", "Le client"], "answer": 1, "explanation": "Le convoyeur est l''ambassadeur de Transports Ligneo."}, {"question": "En cas d''incident mineur, le convoyeur doit :", "choices": ["Le signaler immédiatement", "L''oublier", "Le réparer"], "answer": 0, "explanation": "Tout incident doit être signalé."}, {"question": "Quelle attitude est attendue face aux procédures de sécurité ?", "choices": ["Improviser si besoin", "Respecter strictement", "Adapter selon le client"], "answer": 1, "explanation": "Les procédures de sécurité sont non négociables."}, {"question": "La ponctualité est :", "choices": ["Optionnelle", "Un standard obligatoire", "Au choix du convoyeur"], "answer": 1, "explanation": "La ponctualité est un standard Ligneo."}, {"question": "Un dossier mission incomplet doit être :", "choices": ["Complété avant le départ", "Ignoré", "Résolu sur place"], "answer": 0, "explanation": "Le dossier doit être complet avant le départ."}, {"question": "La carte grise manque au dossier. Que faire ?", "choices": ["Partir sans", "Signaler au dispatch", "Photocopier un autre document"], "answer": 1, "explanation": "Les documents manquants doivent être signalés au dispatch."}, {"question": "Au point de retrait, on se présente :", "choices": ["Anonymement", "Avec nom et provenance Transports Ligneo", "En donnant juste le nom du client"], "answer": 1, "explanation": "Présentation professionnelle requise."}, {"question": "Avant de signer, on vérifie :", "choices": ["L''état visuel et le kilométrage", "Rien", "Uniquement les clés"], "answer": 0, "explanation": "L''état et le kilométrage doivent être vérifiés."}, {"question": "Les documents obligatoires incluent :", "choices": ["Carte grise et assurance", "Permis du convoyeur uniquement", "Contrat de mission uniquement"], "answer": 0, "explanation": "Carte grise et assurance sont obligatoires."}, {"question": "Combien de faces extérieures photographier au départ ?", "choices": ["1", "2", "4"], "answer": 2, "explanation": "4 faces extérieures."}, {"question": "Un état des lieux vierge peut-il être signé ?", "choices": ["Oui", "Non", "Parfois"], "answer": 1, "explanation": "Jamais signer un état des lieux vierge."}, {"question": "En cas de dommage au départ, on :", "choices": ["L''ignore", "Le documente et le signale", "Le répare"], "answer": 1, "explanation": "Documenter et signaler."}, {"question": "L''intérieur doit-il être photographié ?", "choices": ["Oui", "Non", "Uniquement s''il est sale"], "answer": 0, "explanation": "L''intérieur et le tableau de bord doivent être photographiés."}, {"question": "Le kilométrage est noté :", "choices": ["Au départ et à l''arrivée", "Uniquement à l''arrivée", "Jamais"], "answer": 0, "explanation": "Au départ et à l''arrivée."}, {"question": "La conduite attendue est :", "choices": ["Sportive", "Souple et respectueuse", "Lente"], "answer": 1, "explanation": "Souple et respectueuse du code de la route."}, {"question": "Le téléphone au volant est :", "choices": ["Autorisé", "Interdit", "Toléré"], "answer": 1, "explanation": "Interdit."}, {"question": "En cas de pluie forte, on :", "choices": ["Augmente la vitesse", "Adapte la vitesse et les distances", "S''arrête sur la bande d''arrêt d''urgence"], "answer": 1, "explanation": "Adapter la conduite aux conditions."}, {"question": "Sur un long trajet, on fait :", "choices": ["Des pauses", "Aucune pause", "Le plein seulement"], "answer": 0, "explanation": "Pauses régulières."}, {"question": "Le client demande d''aller plus vite. Que faire ?", "choices": ["Obéir", "Refuser poliment et respecter les limites", "Prendre un raccourci"], "answer": 1, "explanation": "Respecter le code de la route."}, {"question": "Un client mécontent doit être :", "choices": ["Écouté calmement", "Ignoré", "Contesté"], "answer": 0, "explanation": "Écoute calme et remontée."}, {"question": "Une demande hors mission doit être :", "choices": ["Acceptée directement", "Remontée au dispatch", "Refusée brutalement"], "answer": 1, "explanation": "Remontée au dispatch."}, {"question": "Le respect du client passe avant :", "choices": ["La rapidité", "La sécurité", "Les documents"], "answer": 0, "explanation": "Respect avant rapidité."}, {"question": "En cas de retard, on prévient :", "choices": ["Le client et le dispatch", "Personne", "Seulement le dispatch"], "answer": 0, "explanation": "Client et dispatch."}, {"question": "La communication doit être :", "choices": ["Claire et professionnelle", "Brève et sèche", "Informelle"], "answer": 0, "explanation": "Claire et professionnelle."}, {"question": "En cas d''accident, la priorité est :", "choices": ["Les personnes", "Le véhicule", "Le client"], "answer": 0, "explanation": "Sécuriser les personnes."}, {"question": "Un incident mineur doit être :", "choices": ["Caché", "Signalé et photographié", "Réparé"], "answer": 1, "explanation": "Signalé et photographié."}, {"question": "En cas de panne, on contacte :", "choices": ["Le dispatch et l''assistance", "Un garagiste au hasard", "Personne"], "answer": 0, "explanation": "Dispatch et assistance."}, {"question": "Après un accident, on ne déplace le véhicule que si :", "choices": ["C''est sûr et après avoir documenté", "Le client le demande", "La police arrive"], "answer": 0, "explanation": "Sécurité et documentation d''abord."}, {"question": "Peut-on reconnaître sa responsabilité seul après un accident ?", "choices": ["Oui", "Non", "Parfois"], "answer": 1, "explanation": "Ne pas reconnaître de responsabilité seul."}, {"question": "L''application Ligneo doit être :", "choices": ["À jour et connectée", "Éteinte", "Utilisée seulement au début"], "answer": 0, "explanation": "À jour et connectée pendant la mission."}, {"question": "Les photos doivent être :", "choices": ["Uploadées immédiatement", "Gardées sur le téléphone", "Envoyées par email"], "answer": 0, "explanation": "Uploadées immédiatement."}, {"question": "Le statut de mission est mis à jour :", "choices": ["À chaque étape clé", "À la fin seulement", "Jamais"], "answer": 0, "explanation": "À chaque étape clé."}, {"question": "Avant la mission, on vérifie :", "choices": ["Batterie, connexion, version app", "Rien", "Uniquement le GPS"], "answer": 0, "explanation": "Batterie, connexion, version."}, {"question": "La signature électronique sert à :", "choices": ["Valider l''état des lieux", "Décoration", "Rien"], "answer": 0, "explanation": "Valider l''état des lieux."}, {"question": "Les données client sont :", "choices": ["Confidentielles", "Publiques", "Partageables"], "answer": 0, "explanation": "Confidentielles."}, {"question": "Le RGPD protège :", "choices": ["Les données personnelles", "Les véhicules", "Les routes"], "answer": 0, "explanation": "Données personnelles."}, {"question": "Un objet personnel trouvé doit être :", "choices": ["Signalé via l''app", "Gardé", "Jeté"], "answer": 0, "explanation": "Signalé via l''app."}, {"question": "Peut-on poster des photos du client sur les réseaux ?", "choices": ["Non", "Oui", "Oui sans le visage"], "answer": 0, "explanation": "Non, jamais sans accord."}, {"question": "Après la mission, on conserve les données client :", "choices": ["Non", "Oui", "Uniquement le nom"], "answer": 0, "explanation": "On ne conserve pas les données."}, {"question": "La mission se termine après :", "choices": ["Signature et remise des clés", "L''arrivée", "Le paiement"], "answer": 0, "explanation": "Signature et remise des clés."}, {"question": "À la livraison, on compare avec :", "choices": ["L''état des lieux de départ", "Le prix", "L''itinéraire"], "answer": 0, "explanation": "Avec l''état des lieux de départ."}, {"question": "Avant la livraison, on prévient le client :", "choices": ["De l''heure d''arrivée", "Du prix", "De notre nom"], "answer": 0, "explanation": "De l''heure d''arrivée."}, {"question": "Un écart constaté doit être :", "choices": ["Documenté et expliqué", "Ignoré", "Payé par le convoyeur"], "answer": 0, "explanation": "Documenté et expliqué."}, {"question": "Les clés sont remises :", "choices": ["À la personne identifiée sur la mission", "À n''importe qui", "Sur le siège"], "answer": 0, "explanation": "À la personne identifiée."}, {"question": "Les 10 règles d''or incluent :", "choices": ["La sécurité avant tout", "La vitesse avant tout", "Le silence avant tout"], "answer": 0, "explanation": "La sécurité avant tout."}, {"question": "Un état des lieux non fait signifie :", "choices": ["Mission non protégée", "Mission plus rapide", "Mission terminée"], "answer": 0, "explanation": "Mission non protégée."}, {"question": "L''image de Ligneo, c''est :", "choices": ["Le convoyeur", "Le site web", "Le dispatch"], "answer": 0, "explanation": "Le convoyeur."}, {"question": "La communication avec le dispatch est :", "choices": ["Continue", "Uniquement en cas de problème", "Inutile"], "answer": 0, "explanation": "Continue."}, {"question": "La qualité se joue :", "choices": ["À chaque étape", "Uniquement à la livraison", "Uniquement au départ"], "answer": 0, "explanation": "À chaque étape."}]'::jsonb,
